import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  output,
  signal,
} from '@angular/core';

@Component({
  selector: 'rm-ng-star-rating',
  changeDetection: ChangeDetectionStrategy.Eager,
  templateUrl: './rm-ng-star-rating.component.html',
  styleUrls: ['./rm-ng-star-rating.component.css'],
  host: {
    '[style.--star-color]': 'color()',
    '[style.--star-empty-color]': 'emptyColor()',
    '[style.--star-size]': 'size()',
  },
})
export class RmNgStarRatingComponent {
  // Inputs (signal-based)
  readonly color = input<string>('gold');
  readonly emptyColor = input<string>('lightgray');
  readonly size = input<string>('40px');
  readonly rating = input<number>(0);
  readonly starCount = input<number>(5);
  readonly readOnly = input<boolean>(false);
  readonly allowHalf = input<boolean>(true);

  // Output (signal-based)
  readonly ratingUpdated = output<number>();

  // Internal state
  private readonly hovered = signal(0);
  private readonly hoveredRating = signal(0);

  readonly starsArray = computed(() =>
    Array.from({ length: this.starCount() }),
  );

  onMouseEnter(index: number, event: MouseEvent): void {
    if (this.readOnly()) {
      return;
    }
    if (this.allowHalf()) {
      this.hoveredRating.set(this.calculateRating(index, event));
    } else {
      this.hoveredRating.set(index);
    }
    this.hovered.set(index);
  }

  onMouseLeave(): void {
    if (this.readOnly()) {
      return;
    }
    this.hovered.set(0);
    this.hoveredRating.set(0);
  }

  onClick(index: number, event?: MouseEvent): void {
    if (this.readOnly()) {
      return;
    }
    const newRating =
      this.allowHalf() && event
        ? this.calculateRating(index, event)
        : index;
    this.ratingUpdated.emit(newRating);
  }

  getStarClass(index: number): string {
    const value = this.hoveredRating() || this.rating();
    if (value >= index) {
      return 'star-filled';
    }
    if (this.allowHalf() && value + 0.5 >= index) {
      return 'star-half-filled';
    }
    return 'star-empty';
  }

  private calculateRating(index: number, event?: MouseEvent): number {
    if (!event) {
      return index;
    }
    const starElement = event.target as HTMLElement;
    const { left, width } = starElement.getBoundingClientRect();
    const x = event.clientX - left;
    return x < width / 2 ? index - 0.5 : index;
  }
}
